<?php
declare(strict_types=1); require_once __DIR__.'/lib/auth.php';$admin=require_admin();$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 try{
  if($action==='create'){$name=trim((string)$_POST['name']);$phone=trim((string)$_POST['phone']);$email=strtolower(trim((string)$_POST['email']));$pass=(string)$_POST['password'];if($name===''||$phone===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Thông tin tạo User chưa hợp lệ.');$q=db()->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())throw new RuntimeException('Email đã tồn tại.');db()->prepare("INSERT INTO users(name,phone,email,password_hash,status,role,expires_at,email_verified_at) VALUES(?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 30 DAY),NOW())")->execute([$name,$phone,$email,password_hash($pass,PASSWORD_DEFAULT),'active','user']);$msg='Đã tạo User mới, mặc định 30 ngày.';}
  elseif($action==='renew'){$days=max(1,min(3650,(int)$_POST['days']));$q=db()->prepare("UPDATE users SET expires_at=CASE WHEN expires_at IS NOT NULL AND expires_at>NOW() THEN DATE_ADD(expires_at,INTERVAL ? DAY) ELSE DATE_ADD(NOW(),INTERVAL ? DAY) END,status='active',email_verified_at=COALESCE(email_verified_at,NOW()) WHERE id=? AND role='user'");$q->execute([$days,$days,$id]);$msg='Đã gia hạn tài khoản.';}
  elseif($action==='password'){$pass=(string)$_POST['password'];if(strlen($pass)<8)throw new RuntimeException('Mật khẩu phải có ít nhất 8 ký tự.');db()->prepare('UPDATE users SET password_hash=? WHERE id=? AND role="user"')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);$msg='Đã đổi mật khẩu User.';}
  elseif($action==='status'){$status=($_POST['status']??'')==='blocked'?'blocked':'active';db()->prepare('UPDATE users SET status=? WHERE id=? AND role="user"')->execute([$status,$id]);$msg='Đã cập nhật trạng thái.';}
 }catch(Throwable $e){$error=$e->getMessage()?:'Không thể thực hiện thao tác.';}
}
$users=db()->query("SELECT id,name,phone,email,status,expires_at,last_login_at,created_at FROM users WHERE role='user' ORDER BY id DESC")->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý tài khoản</title><link rel="stylesheet" href="assets/css/app.css"></head><body><main class="app"><header class="top"><div class="brand"><div class="logo">▶</div><div><h1>Quản lý tài khoản</h1><p>VideoDubing AI · Admin</p></div></div><div class="userbar"><span><?=htmlspecialchars($admin['name'])?></span><a href="logout.php">Đăng xuất</a></div></header>
<section class="panel"><div class="section-title">Tạo User mới</div><?php if($msg):?><div class="alert ok"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" class="admin-create"><input type="hidden" name="action" value="create"><div class="grid"><div class="field"><label>Họ tên</label><input class="input" name="name" required></div><div class="field"><label>Di động</label><input class="input" name="phone" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Mật khẩu</label><input class="input" type="password" name="password" minlength="8" required></div></div><button class="primary">＋ Tạo User</button></form></section>
<section class="panel"><div class="section-title">Danh sách User</div><div class="table-wrap"><table><thead><tr><th>Họ tên</th><th>Di động</th><th>Email</th><th>Trạng thái</th><th>Hạn</th><th>Thao tác</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars((string)$u['phone'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><span class="badge <?=$u['status']==='active'?'ok':'error'?>"><?=htmlspecialchars($u['status'])?></span></td><td><?=htmlspecialchars((string)$u['expires_at'])?></td><td><div class="admin-actions"><form method="post" class="renew"><input type="hidden" name="action" value="renew"><input type="hidden" name="id" value="<?=$u['id']?>"><select name="days"><option value="7">+7 ngày</option><option value="30" selected>+30 ngày</option><option value="90">+90 ngày</option><option value="180">+180 ngày</option><option value="365">+365 ngày</option></select><button class="secondary">Gia hạn</button></form><form method="post" class="inline-form"><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=$u['id']?>"><input class="input compact" type="password" name="password" minlength="8" placeholder="Mật khẩu mới" required><button class="secondary">Đổi MK</button></form><form method="post"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'blocked':'active'"><button class="secondary"><?=$u['status']==='active'?'Khóa':'Mở khóa'?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>